package com.learn.hub.topic;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class TopicListTest {

    private TopicService service;

    @BeforeEach
    void setUp() {
        // fixture(...) 返回 ContentModels.TopicDocument，字段多时抽到独立夹具类
        service = new TopicService(new ContentCatalog(
                Map.of("redis", fixture("redis", "cache", "published"),
                       "secret", fixture("secret", "cache", "draft")),
                Map.of()));
    }

    @ParameterizedTest(name = "page={0}, size={1} 应被拒绝")
    @CsvSource({"-1, 20", "0, 0", "0, 101"})
    void invalidPagingIsRejected(int page, int size) {
        assertThrows(IllegalArgumentException.class,
                () -> service.list(null, null, null, null, page, size));
    }

    @Test
    void listHidesDrafts() {
        var res = service.list(null, null, null, null, 0, 20);

        assertAll(
                () -> assertEquals(1, res.total(), "草稿不应计入 total"),
                () -> assertEquals("redis", res.items().getFirst().slug()),
                () -> assertTrue(res.items().stream().noneMatch(i -> "draft".equals(i.status())))
        );
    }
}

package com.learn.hub.topic;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataAccessResourceFailureException;

import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class TopicQueryServiceTest {

    @Mock
    private TopicRepository repository;

    @InjectMocks
    private TopicQueryService service;

    @Test
    void missingTopicBecomesNotFound() {
        when(repository.findBySlug("nope")).thenReturn(Optional.empty());

        NotFoundException ex = assertThrows(NotFoundException.class, () -> service.detail("nope"));

        assertEquals("TOPIC_NOT_FOUND", ex.getCode());
        verify(repository).findBySlug("nope");
        verify(repository, never()).save(any());
    }

    @Test
    void databaseFailureIsWrapped() {
        when(repository.findBySlug(anyString()))
                .thenThrow(new DataAccessResourceFailureException("connection refused"));

        assertThrows(ServiceUnavailableException.class, () -> service.detail("redis"));
    }
}

package com.learn.hub.web;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(TopicController.class)
class TopicControllerSliceTest {

    @Autowired
    private MockMvc mvc;

    // Spring Boot 3.4+ 用 @MockitoBean 取代已废弃的 @MockBean
    @MockitoBean
    private TopicService service;

    @Test
    void unknownSlugReturns404WithErrorCode() throws Exception {
        when(service.detail("nope"))
                .thenThrow(new NotFoundException("TOPIC_NOT_FOUND", "学习项不存在"));

        mvc.perform(get("/api/v1/topics/nope"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("TOPIC_NOT_FOUND"))
                .andExpect(jsonPath("$.traceId").isNotEmpty());
    }
}
